// Prepare sources for processing
const items = $input.all();
const settings = items[0]?.json || {};

const sources = items.map(item => ({
  json: {
    source_id: item.json.id,
    source_name: item.json.name,
    url: item.json.url,
    genre: item.json.genre,
    user_id: item.json.user_id,
    max_per_source: item.json.max_per_source || 15,
    max_total: item.json.max_total_articles || 200,
    summary_tone: item.json.summary_tone || 'Professional',
    why_focus: item.json.why_matters_focus || 'Business Focus',
    recipient_email: item.json.recipient_email,
    email_greeting: item.json.email_greeting,
    email_footer: item.json.email_footer,
    digest_id: $('Create Digest').first().json.id
  }
}));

return sources.slice(0, 20); // Limit to 20 sources

// Discover article links from homepage
const items = $input.all();
const allArticles = [];

for (const item of items) {
  const sourceUrl = item.json.url || '';
  const sourceName = item.json.source_name || '';
  const genre = item.json.genre || '';
  const maxPerSource = item.json.max_per_source || 15;
  const metadata = {
    source_id: item.json.source_id,
    user_id: item.json.user_id,
    digest_id: item.json.digest_id,
    summary_tone: item.json.summary_tone,
    why_focus: item.json.why_focus,
    recipient_email: item.json.recipient_email,
    email_greeting: item.json.email_greeting,
    email_footer: item.json.email_footer,
    max_total: item.json.max_total
  };

  let html = item.json.data || item.json.body || '';
  if (typeof html !== 'string') continue;
  if (html.length > 300000) html = html.substring(0, 300000);

  let baseUrl;
  try {
    baseUrl = new URL(sourceUrl).origin;
  } catch (e) { continue; }

  // Extract links
  const linkPattern = /href=["']([^"']{10,200})["']/gi;
  const found = [];
  let match;

  while ((match = linkPattern.exec(html)) !== null && found.length < 50) {
    let href = match[1];

    // Skip non-articles
    if (href.startsWith('#') || href.startsWith('javascript:') || href.startsWith('mailto:')) continue;
    if (/\.(css|js|png|jpg|gif|svg|ico|pdf|xml|rss)$/i.test(href)) continue;
    if (/(\/tag\/|\/category\/|\/author\/|\/search|\/login|\/subscribe|\/about|\/contact|\/privacy|\/terms)/i.test(href)) continue;
    if (/(facebook|twitter|linkedin|instagram|youtube|tiktok)\.com/i.test(href)) continue;

    // Resolve relative URLs
    if (href.startsWith('/')) {
      href = baseUrl + href;
    } else if (!href.startsWith('http')) {
      continue;
    }

    // Must be same domain or subdomain
    try {
      const hrefHost = new URL(href).hostname.replace('www.', '');
      const baseHost = new URL(baseUrl).hostname.replace('www.', '');
      if (!hrefHost.includes(baseHost) && !baseHost.includes(hrefHost)) continue;
    } catch (e) { continue; }

    // Skip homepage
    if (href.replace(/\/$/, '') === baseUrl.replace(/\/$/, '')) continue;

    found.push(href);
  }

  // Dedupe and limit
  const unique = [...new Set(found)].slice(0, maxPerSource);

  for (const url of unique) {
    allArticles.push({
      json: {
        article_url: url,
        source_name: sourceName,
        genre: genre,
        ...metadata
      }
    });
  }
}

if (allArticles.length === 0) {
  return [{ json: { error: true, reason: 'No articles found' } }];
}

// Apply max total limit
const maxTotal = allArticles[0]?.json.max_total || 200;
return allArticles.slice(0, Math.min(maxTotal, 50)); // Cap at 50 for n8n Cloud

// Extract article content
const items = $input.all();
const articles = [];

for (const item of items) {
  const articleUrl = item.json.article_url || '';
  const sourceName = item.json.source_name || '';
  const genre = item.json.genre || '';
  const metadata = {
    source_id: item.json.source_id,
    user_id: item.json.user_id,
    digest_id: item.json.digest_id,
    summary_tone: item.json.summary_tone,
    why_focus: item.json.why_focus,
    recipient_email: item.json.recipient_email,
    email_greeting: item.json.email_greeting,
    email_footer: item.json.email_footer
  };

  let html = item.json.data || item.json.body || '';
  if (typeof html !== 'string' || html.length < 500) continue;
  if (html.length > 200000) html = html.substring(0, 200000);

  // Extract title
  let title = '';
  const ogTitle = html.match(/property=["']og:title["'][^>]*content=["']([^"']+)["']/i) ||
                  html.match(/content=["']([^"']+)["'][^>]*property=["']og:title["']/i);
  if (ogTitle) title = ogTitle[1];
  if (!title) {
    const h1 = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);
    if (h1) title = h1[1].trim();
  }
  if (!title) {
    const titleTag = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    if (titleTag) title = titleTag[1].trim();
  }
  if (!title) continue;

  // Clean title
  title = title.replace(/\s*[|\-–—]\s*[^|\-–—]*$/, '').trim();

  // Extract publish date
  let publishDate = null;

  const jsonLd = html.match(/"datePublished"\s*:\s*"([^"]+)"/i);
  if (jsonLd) publishDate = jsonLd[1];

  if (!publishDate) {
    const ogDate = html.match(/property=["']article:published_time["'][^>]*content=["']([^"']+)["']/i) ||
                   html.match(/content=["']([^"']+)["'][^>]*property=["']article:published_time["']/i);
    if (ogDate) publishDate = ogDate[1];
  }

  if (!publishDate) {
    const timeEl = html.match(/<time[^>]*datetime=["']([^"']+)["']/i);
    if (timeEl) publishDate = timeEl[1];
  }

  // Validate date is recent (within 7 days)
  if (publishDate) {
    try {
      const pubDate = new Date(publishDate);
      const now = new Date();
      const daysDiff = (now - pubDate) / (1000 * 60 * 60 * 24);
      if (daysDiff < 0 || daysDiff > 7) continue;
    } catch (e) { }
  }

  // Extract paragraphs
  const paragraphs = [];
  const pRegex = /<p[^>]*>([^<]{30,})<\/p>/gi;
  let pMatch;
  while ((pMatch = pRegex.exec(html)) !== null && paragraphs.length < 15) {
    const text = pMatch[1].replace(/<[^>]*>/g, '').trim();
    if (text.length > 30) paragraphs.push(text);
  }
  const content = paragraphs.join(' ').substring(0, 3000);
  if (content.length < 100) continue;

  articles.push({
    json: {
      url: articleUrl,
      title: title.substring(0, 250),
      content: content,
      source_name: sourceName,
      genre: genre,
      published_at: publishDate,
      ...metadata
    }
  });
}

if (articles.length === 0) {
  return [{ json: { no_articles: true } }];
}

return articles.slice(0, 30); // Max 30 for AI processing

